def box(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{f}" stroke="{s}" stroke-width="3"/><text x="{x+w/2}" y="{y+h/2+7}" text-anchor="middle" font-size="{fs}" font-weight="800" fill="#0B2545" font-family="sans-serif">{t}</text>'
def svg(h,b): return f'<svg viewBox="0 0 520 {h}" style="width:100%">{b}</svg>'
def dot(x,y,col,r=9): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{col}" stroke="#0B2545" stroke-width="2"/>'
S=[]
S.append(TITLE('TIN HỌC · TRÍ TUỆ NHÂN TẠO 2','HỌC MÁY CƠ BẢN','Học máy là gì, học có giám sát – không giám sát – tăng cường, phân loại, hồi quy, thuật toán k-NN.',['học máy','có giám sát','phân loại','hồi quy','k-NN']))
S.append(goals(c,B,['Nêu <b>khái niệm học máy</b> và quy trình.','Phân biệt học <b>có giám sát, không giám sát, tăng cường</b>.','Phân biệt bài toán <b>phân loại</b> và <b>hồi quy</b>.','Hiểu và <b>tính tay</b> thuật toán <b>k-NN</b>.','Cài đặt k-NN bằng <b>Python</b>.'],['Học máy là gì','Các kiểu học','Phân loại, hồi quy','Thuật toán k-NN','Trọng tâm, HSG']))
